#!/usr/bin/env bash
# Step 4 - Compile the INT8 xmodel for the board's DPU (run INSIDE the Vitis AI 3.5 docker).
#
#   bash 4_compile.sh ZCU104          # or ZCU102 / KV260
#
# In the compiler log, look for:  "DPU subgraph number 1"
# More than 1 means some op fell off the DPU - re-run step 3 with --mode inspect to find it.
#
# If you build your OWN DPU hardware (custom Vivado design / different B-size / clock), use the
# arch.json generated by your Vitis build instead, and check on the board with `xdputil query`
# that the fingerprint matches.
set -euo pipefail

BOARD="${1:-ZCU104}"
XMODEL="${2:-quantize_result/DPUHead_int.xmodel}"
NAME="${3:-yolov8n_face_416}"
ARCH="/opt/vitis_ai/compiler/arch/DPUCZDX8G/${BOARD}/arch.json"

[ -f "$ARCH" ] || { echo "No arch.json for $BOARD at $ARCH"; ls /opt/vitis_ai/compiler/arch/DPUCZDX8G/; exit 1; }

vai_c_xir -x "$XMODEL" -a "$ARCH" -o "compiled_${BOARD}" -n "$NAME"

echo
echo "Done: compiled_${BOARD}/${NAME}.xmodel"
echo "Copy to the board together with dpu_face_app.py, yolo_decode.py and ../w600k_mbf.onnx:"
echo "  scp compiled_${BOARD}/${NAME}.xmodel dpu_face_app.py yolo_decode.py ../w600k_mbf.onnx root@<board-ip>:~/face/"
